script:
app.beginUndoGroup("Glitch Random Position");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.selectedLayers.length < 1) throw new Error("Select at least one layer.");
for (var i = 0; i < comp.selectedLayers.length; i++) {
  var layer = comp.selectedLayers[i];
  var effects = layer.property("ADBE Effect Parade");
  var jitter = effects.addProperty("ADBE Slider Control");
  jitter.name = "Jitter";
  jitter.property(1).setValue(24);
  var position = layer.property("ADBE Transform Group").property("ADBE Position");
  position.expression = 'seedRandom(index, true);\n' +
    'posterizeTime(12);\n' +
    'var amp = effect("Jitter")("Slider");\n' +
    'var p = value;\n' +
    'if (random() > 0.65) {\n' +
    '  var nx = p[0] + random(-amp, amp);\n' +
    '  var ny = p[1] + random(-amp, amp);\n' +
    '  p.length > 2 ? [nx, ny, p[2]] : [nx, ny];\n' +
    '} else {\n' +
    '  value;\n' +
    '}';
}
app.endUndoGroup();
